  ["736009cf8cb76919"] = { "あなたはもう私のささやかな力を超えています。DarnassusのCraftsmen's TerraceにいるナイトエルフのAinethilを訪ねなさい。彼女ならもっと教えてくれます。私も一緒に行けたらよかったのですが。", "." },
  ["7365f99fff8307b8"] = { "ほら、もう一荷だ！", "." },
