  ["738518facb30d9b8"] = { "ああ、釣り人仲間か。もしかして少し訓練が必要かい? 一つや2つ、教えてあげられるかもしれないよ?", "." },
  ["738e8328a3943499"] = { "%sはすさまじい咆哮を上げ、近くの敵に知らせた！", "." },
  ["739c5ed2f9370bee"] = { "お前たちは主を裏切ったのだ、定命の者どもよぉ……さらばだ！", "." },
